Vector2Int free=Vector2Int.zero;bool found=false;for(int y=0;y<t.Backpack.Height&&!found;y++)for(int x=0;x<t.Backpack.Width&&!found;x++)if(t.Backpack.CanPlace(chosen,new Vector2Int(x,y))){free=new Vector2Int(x,y);found=true;}
ev.position=RectTransformUtility.WorldToScreenPoint(null,bags.gridContainer.TransformPoint(new Vector3((free.x+.5f)*bags.cellSize,-(free.y+.5f)*bags.cellSize,0)));
starter.OnBeginDrag(ev);starter.OnDrag(ev);starter.OnEndDrag(ev);
